insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000070001', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000009', 'multiple_choice', 'easy', 'published', 'Qual é o domínio real de $f(x)=\sqrt{2-x}$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000700011', '40000000-0000-4000-8000-000000070001', 'A', '$(-\infty,2]$', 1), ('50000000-0000-4000-8000-000000700012', '40000000-0000-4000-8000-000000070001', 'B', '$[2,\infty)$', 2), ('50000000-0000-4000-8000-000000700013', '40000000-0000-4000-8000-000000070001', 'C', '$(-\infty,2)$', 3), ('50000000-0000-4000-8000-000000700014', '40000000-0000-4000-8000-000000070001', 'D', '$mathbb{R}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000070001', '50000000-0000-4000-8000-000000700011') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000070001', '30000000-0000-4000-8000-000000000012', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000700011', '40000000-0000-4000-8000-000000070001', 'O radicando de uma raiz quadrada precisa ser não negativo.', 1), ('60000000-0000-4000-8000-000000700012', '40000000-0000-4000-8000-000000070001', 'Resolva a desigualdade antes de escrever o intervalo.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000070001', '$(-\infty,2]$.', 'Uma raiz quadrada real só existe quando a expressão interna é maior ou igual a zero. O ponto em que o radicando zera deve ser incluído, pois a raiz de zero existe. A desigualdade determina todos os valores permitidos de x e o intervalo é a forma mais clara de registrar o domínio.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700011', '40000000-0000-4000-8000-000000070001', 'Identifique a informação', 'A raiz quadrada é a única parte que pode restringir x.', 1), ('70000000-0000-4000-8000-000000700012', '40000000-0000-4000-8000-000000070001', 'Escreva a condição', '$2-x\ge0$.', 2), ('70000000-0000-4000-8000-000000700013', '40000000-0000-4000-8000-000000070001', 'Faça o cálculo', '$x\le2$.', 3), ('70000000-0000-4000-8000-000000700014', '40000000-0000-4000-8000-000000070001', 'Interprete o resultado', 'Todos os números menores ou iguais a 2 são aceitos.', 4), ('70000000-0000-4000-8000-000000700015', '40000000-0000-4000-8000-000000070001', 'Confira a restrição', '$x=2$ produz raiz de zero e precisa permanecer no domínio.', 5)
