insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000700161', '40000000-0000-4000-8000-000000070016', 'A', '$x=e^{6}$', 1), ('50000000-0000-4000-8000-000000700162', '40000000-0000-4000-8000-000000070016', 'B', '$x=6e$', 2), ('50000000-0000-4000-8000-000000700163', '40000000-0000-4000-8000-000000070016', 'C', '$x=e^{- 6}$', 3), ('50000000-0000-4000-8000-000000700164', '40000000-0000-4000-8000-000000070016', 'D', '$x=6$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000070016', '50000000-0000-4000-8000-000000700161') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000070016', '30000000-0000-4000-8000-000000000015', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000700161', '40000000-0000-4000-8000-000000070016', 'Exponencie os dois lados com base e.', 1), ('60000000-0000-4000-8000-000000700162', '40000000-0000-4000-8000-000000070016', 'Lembre que o logaritmo natural só aceita entradas positivas.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000070016', '$x=e^{6}$.', 'O logaritmo natural e a exponencial de base e são funções inversas. Ao aplicar a exponencial aos dois lados, o logaritmo é desfeito e resta x. A solução encontrada é automaticamente positiva, portanto respeita o domínio do logaritmo e não exige descartar nenhuma raiz adicional.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700161', '40000000-0000-4000-8000-000000070016', 'Identifique a informação', '$\ln(x)$ é definido somente para valores positivos de x.', 1), ('70000000-0000-4000-8000-000000700162', '40000000-0000-4000-8000-000000070016', 'Escreva a condição', '$e^{\ln(x)}=e^{6}$.', 2), ('70000000-0000-4000-8000-000000700163', '40000000-0000-4000-8000-000000070016', 'Faça o cálculo', '$x=e^{6}$.', 3), ('70000000-0000-4000-8000-000000700164', '40000000-0000-4000-8000-000000070016', 'Interprete o resultado', 'A exponencial desfaz o logaritmo natural.', 4), ('70000000-0000-4000-8000-000000700165', '40000000-0000-4000-8000-000000070016', 'Confira a restrição', '$e^{6}>0$, logo a condição de domínio é satisfeita.', 5)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000070017', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000009', 'multiple_choice', 'medium', 'published', 'Se $f(x)=8x-7$, qual é $f^{-1}(x)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000700171', '40000000-0000-4000-8000-000000070017', 'A', '$\frac{x+7}{8}$', 1), ('50000000-0000-4000-8000-000000700172', '40000000-0000-4000-8000-000000070017', 'B', '$\frac{x-7}{8}$', 2), ('50000000-0000-4000-8000-000000700173', '40000000-0000-4000-8000-000000070017', 'C', '$8x+7$', 3), ('50000000-0000-4000-8000-000000700174', '40000000-0000-4000-8000-000000070017', 'D', '$\frac{8}{x+7}$', 4)
