insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000700171', '40000000-0000-4000-8000-000000070017', 'Troque f de x por y e isole x.', 1), ('60000000-0000-4000-8000-000000700172', '40000000-0000-4000-8000-000000070017', 'A inversa desfaz a multiplicação por 8 e a subtração de 7.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000070017', '$f^{-1}(x)=\frac{x+7}{8}$.', 'Para encontrar uma inversa, começamos com a saída y e recuperamos a entrada x. A ordem das operações precisa ser desfeita ao contrário: primeiro somamos o termo que havia sido subtraído, depois dividimos pelo coeficiente. A fórmula final pode ser conferida compondo f com sua inversa e obtendo x.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
