insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000700211', '40000000-0000-4000-8000-000000070021', 'A', 'Deslocar 2 unidades à direita e 1 para cima.', 1), ('50000000-0000-4000-8000-000000700212', '40000000-0000-4000-8000-000000070021', 'B', 'Deslocar 2 unidades à esquerda e 1 para cima.', 2), ('50000000-0000-4000-8000-000000700213', '40000000-0000-4000-8000-000000070021', 'C', 'Deslocar 1 unidades à direita e 2 para cima.', 3), ('50000000-0000-4000-8000-000000700214', '40000000-0000-4000-8000-000000070021', 'D', 'Refletir no eixo x e deslocar para cima.', 4)
