insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000070021', '30000000-0000-4000-8000-000000000014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000700211', '40000000-0000-4000-8000-000000070021', 'Em f(x-a), o sinal interno desloca o gráfico para a direita.', 1), ('60000000-0000-4000-8000-000000700212', '40000000-0000-4000-8000-000000070021', 'O termo somado fora da função controla o deslocamento vertical.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000070021', 'Deslocar 2 unidades à direita e 1 para cima.', 'Transformações horizontais agem dentro do argumento da função e têm sinal aparentemente invertido: x menos a desloca o gráfico a unidades para a direita. Transformações verticais aparecem fora da função e mantêm o sinal usual. Separar essas duas leituras evita confundir o deslocamento do vértice da parábola.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700211', '40000000-0000-4000-8000-000000070021', 'Identifique a informação', '$g(x)=(x-2)^2+1$ vem de uma parábola padrão.', 1), ('70000000-0000-4000-8000-000000700212', '40000000-0000-4000-8000-000000070021', 'Escreva a condição', '$x-2$ controla a posição horizontal.', 2), ('70000000-0000-4000-8000-000000700213', '40000000-0000-4000-8000-000000070021', 'Faça o cálculo', 'O vértice muda de $(0,0)$ para $(2,1)$.', 3), ('70000000-0000-4000-8000-000000700214', '40000000-0000-4000-8000-000000070021', 'Interprete o resultado', 'Isso equivale a mover para a direita e depois para cima.', 4), ('70000000-0000-4000-8000-000000700215', '40000000-0000-4000-8000-000000070021', 'Confira a restrição', 'A abertura continua para cima, pois o coeficiente quadrático é positivo.', 5)
