insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700291', '40000000-0000-4000-8000-000000070029', 'Identifique a informação', '$g(x)=(x-10)^2+9$ vem de uma parábola padrão.', 1), ('70000000-0000-4000-8000-000000700292', '40000000-0000-4000-8000-000000070029', 'Escreva a condição', '$x-10$ controla a posição horizontal.', 2), ('70000000-0000-4000-8000-000000700293', '40000000-0000-4000-8000-000000070029', 'Faça o cálculo', 'O vértice muda de $(0,0)$ para $(10,9)$.', 3), ('70000000-0000-4000-8000-000000700294', '40000000-0000-4000-8000-000000070029', 'Interprete o resultado', 'Isso equivale a mover para a direita e depois para cima.', 4), ('70000000-0000-4000-8000-000000700295', '40000000-0000-4000-8000-000000070029', 'Confira a restrição', 'A abertura continua para cima, pois o coeficiente quadrático é positivo.', 5)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000070030', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000009', 'multiple_choice', 'hard', 'published', 'Partindo de $y=x^2$, qual transformação produz $g(x)=(x-11)^2+10$?')
