insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000700411', '40000000-0000-4000-8000-000000070041', 'A', '$4$', 1), ('50000000-0000-4000-8000-000000700412', '40000000-0000-4000-8000-000000070041', 'B', '$2$', 2), ('50000000-0000-4000-8000-000000700413', '40000000-0000-4000-8000-000000070041', 'C', '$5$', 3), ('50000000-0000-4000-8000-000000700414', '40000000-0000-4000-8000-000000070041', 'D', '$0$', 4)
