insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000070041', '$c=4$.', 'Em uma função definida por partes, a continuidade no ponto de troca depende de três valores compatíveis: limite pela esquerda, limite pela direita e valor da função. Como o lado direito é constante c, basta escolher c igual ao valor que a expressão da esquerda se aproxima quando x tende ao ponto de corte.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700411', '40000000-0000-4000-8000-000000070041', 'Identifique a informação', 'O possível salto ocorre no ponto $x=2$.', 1), ('70000000-0000-4000-8000-000000700412', '40000000-0000-4000-8000-000000070041', 'Escreva a condição', '$lim_{x\to2^-}(x+2)=2+2$.', 2), ('70000000-0000-4000-8000-000000700413', '40000000-0000-4000-8000-000000070041', 'Faça o cálculo', '$lim_{x\to2^-}f(x)=4$.', 3), ('70000000-0000-4000-8000-000000700414', '40000000-0000-4000-8000-000000070041', 'Interprete o resultado', 'O valor do lado direito é $f(2)=c$.', 4), ('70000000-0000-4000-8000-000000700415', '40000000-0000-4000-8000-000000070041', 'Confira a restrição', '$c=4$ iguala limite e valor da função.', 5)
