insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000800011', '40000000-0000-4000-8000-000000080001', 'A', '$1$', 1), ('50000000-0000-4000-8000-000000800012', '40000000-0000-4000-8000-000000080001', 'B', '$-1$', 2), ('50000000-0000-4000-8000-000000800013', '40000000-0000-4000-8000-000000080001', 'C', '$4$', 3), ('50000000-0000-4000-8000-000000800014', '40000000-0000-4000-8000-000000080001', 'D', '$-2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000080001', '50000000-0000-4000-8000-000000800011') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
