insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000800011', '40000000-0000-4000-8000-000000080001', 'Velocidade instantânea é a derivada da posição.', 1), ('60000000-0000-4000-8000-000000800012', '40000000-0000-4000-8000-000000080001', 'Derive antes de substituir o instante.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000080001', '$v(2)=1$.', 'A derivada transforma a posição em velocidade porque mede a variação instantânea no tempo. O termo quadrático gera uma expressão linear e o termo linear contribui com uma constante negativa. Só depois de obter a regra geral de velocidade substituímos o instante pedido; isso evita usar uma taxa média por engano.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000800011', '40000000-0000-4000-8000-000000080001', 'Observe a estrutura', '$v(t)=s^{\prime}(t)$', 1), ('70000000-0000-4000-8000-000000800012', '40000000-0000-4000-8000-000000080001', 'Escolha a regra', '$s^{\prime}(t)=2t-3$', 2), ('70000000-0000-4000-8000-000000800013', '40000000-0000-4000-8000-000000080001', 'Calcule', '$v(2)=2\cdot2-3$', 3), ('70000000-0000-4000-8000-000000800014', '40000000-0000-4000-8000-000000080001', 'Interprete', '$v(2)=1$', 4), ('70000000-0000-4000-8000-000000800015', '40000000-0000-4000-8000-000000080001', 'Confira', 'A resposta usa unidades de posição por unidade de tempo.', 5)
