insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000080011', '$f^{\prime}(x)=2x^1$.', 'A regra da potência multiplica o coeficiente pelo expoente e reduz esse expoente em uma unidade. Como a função tem um coeficiente externo, ele participa da multiplicação. É importante reduzir somente o expoente de x: alterar a potência sem ajustar o coeficiente produz um resultado que não devolve a função original ao ser integrado.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
