insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000080041', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000010', 'multiple_choice', 'easy', 'published', 'Para $f(x)=x^2-1$, qual ponto pertence ao gráfico e está sobre o eixo x?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000800411', '40000000-0000-4000-8000-000000080041', 'A', '$(1,0)$', 1), ('50000000-0000-4000-8000-000000800412', '40000000-0000-4000-8000-000000080041', 'B', '$(0,1)$', 2), ('50000000-0000-4000-8000-000000800413', '40000000-0000-4000-8000-000000080041', 'C', '$(2,0)$', 3), ('50000000-0000-4000-8000-000000800414', '40000000-0000-4000-8000-000000080041', 'D', '$(0,-1)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000080041', '50000000-0000-4000-8000-000000800411') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000080041', '30000000-0000-4000-8000-000000000030', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000800411', '40000000-0000-4000-8000-000000080041', 'Pontos do eixo x têm coordenada y igual a zero.', 1), ('60000000-0000-4000-8000-000000800412', '40000000-0000-4000-8000-000000080041', 'Iguale a função a zero e fatorize.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000080041', '$(1,0)$.', 'Interseções com o eixo x são zeros da função, pois nesses pontos a altura do gráfico é zero. Ao fatorar uma diferença de quadrados, encontramos duas raízes simétricas. A alternativa pedida apresenta a raiz positiva; verificar a substituição mostra que o valor da função realmente se anula, confirmando que o ponto pertence ao gráfico.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000800411', '40000000-0000-4000-8000-000000080041', 'Observe a estrutura', 'No eixo x, a coordenada vertical vale zero.', 1), ('70000000-0000-4000-8000-000000800412', '40000000-0000-4000-8000-000000080041', 'Escolha a regra', '$x^2-1=0$', 2), ('70000000-0000-4000-8000-000000800413', '40000000-0000-4000-8000-000000080041', 'Calcule', '$(x-1)(x+1)=0$', 3), ('70000000-0000-4000-8000-000000800414', '40000000-0000-4000-8000-000000080041', 'Interprete', '$x=1$ ou $x=-1$', 4), ('70000000-0000-4000-8000-000000800415', '40000000-0000-4000-8000-000000080041', 'Confira', '$f(1)=0$ confirma o ponto escolhido.', 5)
